/*!******************************************!*\
  !*** ./src/admin/js/ilj-broken-links.js ***!
  \******************************************/
(function ($) {
  $(function () {
    var __ = wp.i18n.__;
    var ajaxUrl = ilj_ajax_object.ajaxurl;
    var nonce = ilj_broken_links.nonce;
    var timerBrokenLinks,
      delayBrokenLinks = 3000;
    if (ilj_broken_links.checker_running) {
      timerBrokenLinks = setInterval(function () {
        updateBrokenLinksStatus(timerBrokenLinks);
      }, delayBrokenLinks);
    }

    /**
    * Start Broken Link Scan
    */
    $(document).on('click', '.button.ilj-scan-broken-links', function (e) {
      e.preventDefault();
      var $button = $(this);
      $button.addClass("processing");
      $button.find('.progress-inner').text(__('Processing', 'internal-links'));
      $.ajax({
        url: ajaxUrl,
        type: "POST",
        data: {
          action: 'ilj_scan_broken_links',
          nonce: nonce
        },
        statusCode: {
          500: function (xhr) {
            if (!xhr.responseJSON || !["success", "error"].includes(xhr.responseJSON.status)) {
              console.error("Unexpected server error");
              return;
            }
            alert(xhr.responseJSON.message);
          }
        },
        success: function () {
          alert(__('Broken link scan has started and is running in the background.\n\nYou can continue using the site while the scan completes.', 'internal-links'));
          timerBrokenLinks = setInterval(function () {
            updateBrokenLinksStatus(timerBrokenLinks);
          }, delayBrokenLinks);
        }
      });
    });

    /**
     * Recursive status checker for broken link scan progress.
     *
     * @param {number} timer The interval timer reference used to stop the recursion
     * when the scan completes.
     */
    function updateBrokenLinksStatus(timer) {
      $.ajax({
        url: ajaxUrl,
        type: "POST",
        data: {
          action: "ilj_render_broken_links_info",
          nonce: nonce
        }
      }).done(function (response) {
        if (response.status === 'error') {
          $('.ilj-scan-broken-links').removeClass("processing");
          return;
        }
        var $progress = $('#ilj-scan-broken-links .progress-inner');
        $progress.text(__('Processing', 'internal-links'));
        if (response.is_complete == true) {
          clearInterval(timer);
          setTimeout(function () {
            $('.button.ilj-scan-broken-links').removeClass('processing');
            refreshBrokenLinksTable();
          }, 1500);
        }
      });
    }

    /**
     * Export broken links
     */
    $(document).on('click', 'button.ilj-broken-links-export', function (e) {
      e.preventDefault();
      var $spinner = $(this);
      $spinner.addClass('processing');
      setTimeout(function () {
        var exportUrl = `${window.location.href}&ilj_broken_links_export=1&nonce=${nonce}`;
        $('<iframe/>', {
          src: exportUrl,
          style: 'display: none'
        }).appendTo('body');
        $spinner.removeClass('processing');
      }, 1000);
    });

    /**
     * Ignore a broken link
     */
    $(document).on('click', '.ilj-ignore-broken-link', function (e) {
      e.preventDefault();
      if (!confirm(__('You are about to permanently ignore this link from checking.\n\'Cancel\' to stop, \'OK\' to ignore.', 'internal-links'))) {
        return;
      }
      $.ajax({
        url: ajaxUrl,
        type: "POST",
        data: {
          action: "ilj_broken_links_ignore",
          nonce: nonce,
          link_id: $(this).data('id')
        }
      }).done(function (response) {
        if (response.status === 'error') {
          alert(response.message);
          return;
        }
        refreshBrokenLinksTable();
      });
    });

    /**
     * Restore a previously ignored broken link
     */
    $(document).on('click', '.ilj-remove-ignore-broken-link', function (e) {
      e.preventDefault();
      if (!confirm(__('You are about to remove this ignored link and return it to broken link checking.\n\'Cancel\' to stop, \'OK\' to continue.', 'internal-links'))) {
        return;
      }
      $.ajax({
        url: ajaxUrl,
        type: "POST",
        data: {
          action: "ilj_ignore_broken_links_restore",
          nonce: nonce,
          link_id: $(this).data('id')
        }
      }).done(function (response) {
        if (response.status === 'error') {
          alert(response.message);
          return;
        }
        refreshBrokenLinksTable();
        iljRemoveCurrentViewParam();
      });
    });

    /**
     * Removes the 'current_view' query parameter from the current page URL
     * without reloading the page.
     *
     * Useful for resetting the view back to default (e.g., from "Ignore Links" to "Broken Links").
     */
    function iljRemoveCurrentViewParam() {
      const url = new URL(window.location.href);

      // Check if 'current_view' exists in the URL and remove it
      if (url.searchParams.has('current_view')) {
        url.searchParams.delete('current_view');

        // Update the browser address bar without refreshing the page
        window.history.replaceState({}, document.title, url.toString());
      }
    }

    /**
     * Unlink a broken link from post/term content.
     *
     * Removes the <a href="...">...</a> tag but keeps the anchor text intact.
     */
    $(document).on('click', '.ilj-unlink-broken-link', function (e) {
      e.preventDefault();
      var type = $(this).data('type');
      if ('custom' == type) {
        if (confirm(__('You are about to unlink a Custom Link.\n\nClick \'OK\' to permanently delete this Custom Link. All posts or terms linked to it will have the link removed.\n\nClick \'Cancel\' if you prefer to update the link manually.', 'internal-links'))) {
          $.ajax({
            url: ajaxUrl,
            type: "POST",
            data: {
              action: "ilj_broken_links_unlink_custom_links",
              nonce: nonce,
              link_id: $(this).data('id')
            }
          }).done(function (response) {
            if (response.status === 'error') {
              alert(response.message);
              return;
            }
            refreshBrokenLinksTable();
          });
        }
        return;
      }
      if (!confirm(__('You are about to remove this hyperlink from the content. The anchor text will remain.\n\'Cancel\' to stop, \'OK\' to ignore.', 'internal-links'))) {
        return;
      }
      $.ajax({
        url: ajaxUrl,
        type: "POST",
        data: {
          action: "ilj_broken_links_unlink",
          nonce: nonce,
          link_id: $(this).data('id')
        }
      }).done(function (response) {
        if (response.status === 'error') {
          alert(response.message);
          return;
        }
        refreshBrokenLinksTable();
      });
    });

    /**
     * Reload broken links table HTML via AJAX
     */
    function refreshBrokenLinksTable() {
      var urlParams = new URLSearchParams(window.location.search);
      var currentView = urlParams.get('current_view');
      var data = {
        action: "ilj_broken_links_tables_data",
        nonce: nonce,
        browser_url: window.location.href // send the real admin page URL
      };

      // If `current_view` is present in the URL, include it in the AJAX request
      if (currentView) {
        data.current_view = currentView;
      }
      $.ajax({
        url: ajaxUrl,
        type: "GET",
        data: data
      }).done(function (response) {
        if (response.table) {
          $('.ilj-table-container').html(response.table);
          $('#internal-link-juicer-broken-links-form .subsubsub .broken-links .count').text(response.total_links);
          $('#internal-link-juicer-broken-links-form .subsubsub .ignore-broken-links .count').text(response.total_ignore_links);
        }
      });
    }
  });
})(jQuery);
